@startuml

enum AttendeeStatus {
  Yes
  Maybe
  No
}

enum CompletionStatus {
  ToBeDone
  Done
  NotApplicable
}

class Person {
  + FirstName : string
  + LastName : string
  + EmailAddress : string
  + Password : string
}

class Organizer extends Person {
  + Address : string
  + PhoneNumber : string
}

class Attendee extends Person {}

class Event {
  + Occasion : string
  + StartTime : datetime
  + EndTime : datetime
}

class EventType {
  + Name : string
}

class Location {
  + Name : string
  + Address : string
}

class Task {
  + Description : string
}

class ChecklistTask {
  + Status : CompletionStatus
}

class TaskAssignment {
}

class Registration {
  + Status : AttendeeStatus
}

Organizer "1..*" -- "*" Event : organizes
Organizer "0..1" -- "*" Event : attends
Attendee "0..*" -- "*" Event : invited to
Attendee "1" -- "*" Registration : makes
Registration "*" -- "1" Event : for
Attendee "0..1" -- "*" TaskAssignment : performs
TaskAssignment "*" -- "1" ChecklistTask : assigned to
ChecklistTask "*" -- "1" Event : belongs to
Task "1" -- "*" ChecklistTask : template for
EventType "1" -- "*" Event : categorizes
Location "1" -- "*" Event : hosts

@enduml

